def translate_common_line(line):
    """Translate common patterns found in API doc tables."""
    # Check parameter descriptions
    for eng, chn in PARAM_DESC.items():
        if eng in line:
            line = line.replace(eng, chn)
    return line


def translate_table_header(line):
    """Translate table header labels."""
    replacements = {
        "Properties": "属性",
        "Location": "位置",
        "Type": "类型",
        "Require": "是否必填",
        "Sample": "示例",
        "Properties description": "属性描述",
        "Code": "错误码",
        "Message": "错误信息",
    }
    for eng, chn in replacements.items():
        # Match in table header context with HTML width comments
        pattern = eng + r'( <!-- width:\d+px -->)'
        line = re.sub(pattern, chn + r'\1', line)
    return line


def translate_file_content(content, file_translations):
    """Apply file-specific translations to content."""
    for eng, chn in file_translations.items():
        content = content.replace(eng, chn)
    return content


def process_api_file(content, specific_translations=None):
    """Process a standard API documentation file."""
    lines = content.split('\n')
    result = []
    in_code_block = False
    
    for line in lines:
        original_line = line
        
        # Track code blocks - don't translate inside them (except comments)
        if line.strip().startswith('```'):
            in_code_block = not in_code_block
            result.append(line)
            continue
        
        if in_code_block:
            result.append(line)
            continue
        
        # Don't translate HTML blocks (SVG, divs with styles)
        if '<img src=' in line or '<svg' in line or 'base64,' in line:
            result.append(line)
            continue
        if '<div style=' in line or '</div>' in line or '<p>' in line or '</p>' in line:
            # These will be handled by specific translations
            pass
        
        # Don't translate separator lines
        if line.strip() == '---' or line.strip() == '':
            result.append(line)
            continue
        
        # Translate table headers
        if '| Properties' in line and '<!-- width:' in line:
            line = translate_table_header(line)
        
        # Translate common parameter descriptions in tables
        line = translate_common_line(line)
        
        # Translate section headers
        for eng, chn in SECTION_HEADERS.items():
            if line.strip() == eng or line.startswith(eng):
                if eng == "# Path:" or eng == "# Method:":
                    pass  # Keep as-is
                else:
                    line = line.replace(eng, chn)
        
        # Translate standard link text
        for eng, chn in LINK_TRANS.items():
            if eng in line:
                line = line.replace(eng, chn)
        
        # Apply specific translations for this file
        if specific_translations:
            for eng, chn in specific_translations.items():
                if eng in line:
                    line = line.replace(eng, chn)
        
        result.append(line)
    
    return '\n'.join(result)


