def translate_file(filepath, translations_dict):
    """Read file, apply translations, write back."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    
    for eng, chn in translations_dict.items():
        content = content.replace(eng, chn)
    
    # Apply common translations
    for eng, chn in PARAM_DESC.items():
        content = content.replace(eng, chn)
    
    # Apply section header translations
    content = content.replace("# Common Parameters", "# 通用参数")
    content = content.replace("# Request Query Parameters", "# 请求 Query 参数")
    content = content.replace("# Request Body Parameters", "# 请求 Body 参数")
    content = content.replace("# Request Path Parameters", "# 请求 Path 参数")
    content = content.replace("# Request Sample", "# 请求示例")
    content = content.replace("# Response Parameters", "# 响应参数")
    content = content.replace("# Response Sample", "# 响应示例")
    content = content.replace("# Error Code", "# 错误码")
    content = content.replace("# Error Codes", "# 错误码")
    content = content.replace("# Function Description", "# 功能描述")
    
    # Apply link translations
    content = content.replace(
        "For common parameters, refer to [How to call TikTok Shop APIs - Common Parameters]",
        "通用参数请参考 [如何调用 TikTok Shop APIs - 通用参数]"
    )
    content = content.replace(
        "For common error codes, refer to [How to call TikTok Shop APIs - Common Error Code]",
        "通用错误码请参考 [如何调用 TikTok Shop APIs - 通用错误码]"
    )
    
    # Translate table headers
    content = content.replace("Properties description", "属性描述")
    # Be careful not to replace "Properties" inside code blocks
    # Only replace in table header context
    content = re.sub(
        r'\| Properties (<!-- width:\d+px -->)',
        r'| 属性 \1',
        content
    )
    content = re.sub(
        r'\| Location (<!-- width:\d+px -->)',
        r'| 位置 \1',
        content
    )
    content = re.sub(
        r'\| Type (<!-- width:\d+px -->)',
        r'| 类型 \1',
        content
    )
    content = re.sub(
        r'\| Require (<!-- width:\d+px -->)',
        r'| 是否必填 \1',
        content
    )
    # Sample in table header - be careful not to replace in code
    content = re.sub(
        r'\| Sample (<!-- width:\d+px -->)',
        r'| 示例 \1',
        content
    )
    content = re.sub(
        r'\| Code (<!-- width:\d+px -->)',
        r'| 错误码 \1',
        content
    )
    content = re.sub(
        r'\| Message (<!-- width:\d+px -->)',
        r'| 错误信息 \1',
        content
    )
    content = content.replace("Allowed type: application/json", "允许类型：application/json")
    
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(content)
    
    return True


